// hall block whose roof line rises and falls in waves over the halls; the Event Hall's oval dome (_b), the International
// Conference Hall (_c) and the North Halls 9-11 (_d, 34 m OSM). Roof forms are generic readings of the wavy roof line.
const MK_COL = {W:{c:'#d8d8d2', m:1, fh:4.8, cw:3.6}, GL:{c:'#71838f', m:1, fh:4.8, cw:3.0}, RF:{c:'#b9c0c4', m:0, lk:0.3}, RF2:'#a8aeb2', ST:'#9ea4a8'};
